<?php
ob_start();
$pageTitle='Keranjang'; require_once __DIR__.'/../includes/header.php'; $_SESSION['cart']=$_SESSION['cart']??[];
if($_SERVER['REQUEST_METHOD']==='POST') {if(isset($_POST['remove'])) unset($_SESSION['cart'][(int)$_POST['remove']]); elseif(isset($_POST['update'])) {foreach($_POST['qty']??[] as $id=>$qty){$qty=(int)$qty;if($qty<1)unset($_SESSION['cart'][(int)$id]);else $_SESSION['cart'][(int)$id]=$qty;}} setFlash('success','Keranjang diperbarui.');redirect(BASE_URL.'/buyer/cart.php');}
$all=$conn?[]:getDummyProducts(); if($conn){$ids=array_map('intval',array_keys($_SESSION['cart']));if($ids){$r=$conn->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id IN ('.implode(',',$ids).') AND p.status="available"');while($r&&$row=$r->fetch_assoc())$all[]=$row;}}
$items=[];$total=0;foreach($all as $p)if(isset($_SESSION['cart'][$p['id']])){$q=min((int)$_SESSION['cart'][$p['id']],(int)$p['stock']);$_SESSION['cart'][$p['id']]=$q;$p['quantity']=$q;$p['subtotal']=$q*$p['price'];$items[]=$p;$total+=$p['subtotal'];}
?>
<section class="section"><div class="container"><div class="page-header"><div><h1>Keranjang belanja</h1><p class="text-muted">Periksa kembali pilihanmu sebelum checkout.</p></div></div><?php if(!$items): ?><div class="empty-state"><span class="empty-icon">🛒</span><h3>Keranjangmu masih kosong</h3><p>Yuk temukan barang preloved yang kamu suka.</p><a class="btn btn-primary" href="<?= BASE_URL ?>/buyer/">Jelajahi produk</a></div><?php else: ?><div class="cart-container"><div><form method="post"><?php foreach($items as $p): ?><div class="cart-item"><div class="cart-item-image"><?php if($p['image']): ?><img src="<?= BASE_URL ?>/uploads/products/<?= sanitize($p['image']) ?>" alt=""><?php else: ?>♻️<?php endif; ?></div><div class="cart-item-info"><div class="cart-item-name"><?= sanitize($p['name']) ?></div><div class="cart-item-price"><?= formatRupiah($p['price']) ?></div></div><input aria-label="Jumlah" type="number" min="0" max="<?= (int)$p['stock'] ?>" name="qty[<?= (int)$p['id'] ?>]" value="<?= $p['quantity'] ?>" class="qty-input"><strong><?= formatRupiah($p['subtotal']) ?></strong><button class="btn btn-sm btn-danger" name="remove" value="<?= (int)$p['id'] ?>">Hapus</button></div><?php endforeach; ?><button class="btn btn-outline" name="update" value="1">Perbarui keranjang</button></form></div><aside class="cart-summary"><h3>Ringkasan</h3><div class="cart-summary-row"><span>Subtotal (<?= getCartCount() ?> barang)</span><strong><?= formatRupiah($total) ?></strong></div><div class="cart-summary-row total"><span>Total</span><span><?= formatRupiah($total) ?></span></div><a class="btn btn-primary btn-block" href="<?= BASE_URL ?>/buyer/checkout.php">Lanjut checkout</a></aside></div><?php endif; ?></div></section>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
